// @vitest-environment jsdom
import React from "react";
import {
  act,
  cleanup,
  fireEvent,
  render,
  screen,
} from "@testing-library/react";
import { afterEach, expect, it } from "vitest";
import SafeChangeComposer from "./SafeChangeComposer";
import { ForgeClient } from "../api/ForgeClient";
import { response } from "../../tests/core-test-data";
import fixture from "../../tests/composer-demo2.json";
afterEach(cleanup);

// Fixture generated by the real composer on the DEMO 2 shape (packages/simulation-core/src/composer.ts).
const request = {
  projectId: "TD",
  rootIssueKey: "TD-1",
  source: "JIRA" as const,
  snapshotId: "snap-td-demo2",
  changes: [
    {
      id: "A-migrate-to-v2",
      label: "Move consumers of TD-1 to TD-5",
      operations: [
        {
          op: "MIGRATE_DEPENDENTS" as const,
          fromNodeId: "issue:TD-1",
          toNodeId: "issue:TD-5",
          edgeKinds: ["DEPENDS_ON" as const],
        },
      ],
    },
    {
      id: "B-break-v2",
      label: "Breaking upgrade of TD-5",
      operations: [
        { op: "UPGRADE_NODE" as const, nodeId: "issue:TD-5", breaking: true },
      ],
    },
  ],
};

it("ranks the compatibility phase first, states assumptions, and selecting never executes", async () => {
  const ops: string[] = [];
  const client = new ForgeClient(async (op) => {
    ops.push(op);
    return response(fixture);
  }, 5000);
  render(<SafeChangeComposer client={client} request={request} />);
  await act(async () => {
    fireEvent.click(
      screen.getByRole("button", { name: "Compose safer alternatives" }),
    );
  });
  const items = screen
    .getAllByRole("listitem")
    .filter((li) => li.className.includes("ax-composer__cand"));
  expect(items[0]!.textContent).toMatch(/Compatibility phase for TD-5/);
  expect(items[0]!.textContent).toMatch(/Assumes: A compatibility layer/);
  expect(items[0]!.textContent).toMatch(
    /breaking upgrade of TD-5 → non-breaking upgrade of TD-5/,
  );
  expect(screen.getByText("current plan")).toBeTruthy();
  fireEvent.click(
    screen.getAllByRole("button", { name: "Select for review" })[0]!,
  );
  expect(screen.getByRole("status").textContent).toMatch(
    /not approved or executed/,
  );
  expect(ops).toEqual(["composeSafeChanges"]);
});

it("rejects alternatives for another snapshot", async () => {
  const client = new ForgeClient(
    async () => response({ ...fixture, snapshotId: "other" }),
    5000,
  );
  render(<SafeChangeComposer client={client} request={request} />);
  await act(async () => {
    fireEvent.click(
      screen.getByRole("button", { name: "Compose safer alternatives" }),
    );
  });
  expect(screen.getByRole("alert").textContent).toMatch(
    /Snapshot mismatch|do not match the analysed snapshot/,
  );
});
